INSERT INTO `questions` (`id`, `subtopic_id`, `difficulty`, `question_text`, `code_snippet`, `language`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `est_time_seconds`, `total_attempts_count`, `total_correct_count`, `source_tag`, `created_at`, `is_company_pyq`, `company_name`) VALUES
('1', '1', 'medium', 'A train 150 meters long passes a telegraph post in 12 seconds. What is the speed of the train in km/hr?', NULL, NULL, '36 km/hr', '45 km/hr', '54 km/hr', '60 km/hr', 'B', 'Speed = Distance / Time = 150m / 12s = 12.5 m/s. Convert m/s to km/hr by multiplying by 18/5: 12.5 * (18/5) = 45 km/hr.', '45', '5', '1', 'TCS NQT', '2026-09-15 19:12:00', '1', NULL),
('2', '1', 'easy', 'A car travels at a speed of 60 km/hr. How much distance does it cover in 45 minutes?', NULL, NULL, '40 km', '45 km', '50 km', '55 km', 'B', 'Time = 45 minutes = 45/60 = 0.75 hours. Distance = Speed * Time = 60 * 0.75 = 45 km.', '30', '2', '0', 'Campus Placement', '2026-09-15 19:12:00', '0', NULL),
('3', '1', 'hard', 'Two trains running in opposite directions at 40 km/hr and 50 km/hr cross each other in 12 seconds. If the length of one train is 120m, find the length of the other train.', NULL, NULL, '150 m', '180 m', '200 m', '220 m', 'B', 'Relative speed in opposite direction = 40 + 50 = 90 km/hr = 90 * (5/18) = 25 m/s. Total distance covered = Relative Speed * Time = 25 * 12 = 300m. Length of 2nd train = 300m - 120m = 180m.', '60', '1', '0', 'Infosys Pattern', '2026-09-15 19:12:00', '1', NULL),
('4', '2', 'easy', 'If the price of an article is increased by 20% and then decreased by 20%, what is the net percentage change in price?', NULL, NULL, 'No change', '4% increase', '4% decrease', '2% decrease', 'C', 'Net change formula: a + b + (ab/100). Here a = +20, b = -20. Net change = 20 - 20 + (20 * -20 / 100) = -400/100 = -4% (i.e. 4% decrease).', '30', '0', '0', 'Wipro NLTH', '2026-09-15 19:12:00', '1', NULL),
('5', '2', 'medium', 'A shopkeeper sells a book for $240, making a profit of 20%. What was the cost price of the book?', NULL, NULL, '$180', '$190', '$200', '$210', 'C', 'Selling Price = Cost Price * (1 + Profit%). 240 = Cost Price * 1.20. Cost Price = 240 / 1.20 = $200.', '45', '4', '2', 'General Aptitude', '2026-09-15 19:12:00', '0', NULL),
('6', '4', 'medium', 'Six friends A, B, C, D, E, F are sitting in a circle facing the center. B is between F and C. A is between E and D. F is to the immediate left of D. Who is sitting opposite to B?', NULL, NULL, 'A', 'D', 'E', 'F', 'A', 'Arranging clockwise facing center: F - B - C - E - A - D. B is sitting directly opposite to A.', '50', '1', '0', 'Cognizant GenC', '2026-09-15 19:12:00', '1', NULL),
('7', '5', 'easy', 'Pointing to a photograph, Rohit said, \"She is the daughter of my grandfather\'s only son.\" How is the girl in the photograph related to Rohit?', NULL, NULL, 'Mother', 'Sister', 'Cousin', 'Aunt', 'B', 'Rohit\'s grandfather\'s only son is Rohit\'s father. The daughter of Rohit\'s father is Rohit\'s sister.', '30', '0', '0', 'Blood Relations Standard', '2026-09-15 19:12:00', '0', NULL),
('8', '6', 'easy', 'Find the missing number in the sequence: 4, 9, 19, 39, 79, ?', NULL, NULL, '119', '139', '159', '179', 'C', 'Pattern: (Previous number * 2) + 1. (4*2)+1=9; (9*2)+1=19; (19*2)+1=39; (39*2)+1=79; (79*2)+1 = 159.', '35', '0', '0', 'Series Test', '2026-09-15 19:12:00', '0', NULL),
('9', '8', 'medium', 'Choose the grammatically correct sentence:', NULL, NULL, 'Neither of the two candidates have submitted their resume.', 'Neither of the two candidates has submitted his resume.', 'Neither of the two candidates were submitting resumes.', 'Neither of two candidate submitted their resumes.', 'B', '\'Neither\' takes a singular verb (\'has\') and singular pronoun (\'his\' or \'his/her\'). Therefore, option B is correct.', '40', '2', '1', 'Verbal Standard', '2026-09-15 19:12:00', '0', NULL),
('10', '9', 'medium', 'In a college of 500 students, 60% play Cricket, 40% play Football, and 20% play both. How many students play neither game?', NULL, NULL, '80', '100', '120', '150', 'B', 'Total playing at least one game = %Cricket + %Football - %Both = 60% + 40% - 20% = 80%. Students playing neither = 100% - 80% = 20%. 20% of 500 = 100 students.', '45', '7', '5', 'DI Venn Diagram', '2026-09-15 19:12:00', '0', NULL),
('11', '1', 'medium', 'A man can row 6 km/h in still water. If the speed of the current is 2 km/h, it takes him 4 hours to row to a place and come back. Find the distance to the place.', NULL, NULL, '8 km', '9.6 km', '10 km', '12 km', 'B', 'Downstream speed (u) = 6 + 2 = 8 km/h. Upstream speed (v) = 6 - 2 = 4 km/h. Time formula: T = D/u + D/v => 4 = D/8 + D/4 => 4 = 3D/8 => D = 32/3 = 10.67 or D = (8 * 4 * 4)/(8+4) = 128/12 = 9.6 km (using D = t * (u*v)/(u+v)).', '50', '2', '1', 'TCS NQT PYQ', '2026-09-16 20:28:27', '1', NULL),
('12', '2', 'hard', 'A sum of money becomes 3 times itself in 6 years at Compound Interest. In how many years will it become 27 times itself at the same rate of interest?', NULL, NULL, '12 years', '18 years', '24 years', '30 years', 'B', 'If money becomes 3^1 in 6 years, it becomes (3^1)^n = 3^n in 6 * n years. Here 27 = 3^3. So time required = 6 * 3 = 18 years.', '45', '0', '0', 'TCS NQT PYQ', '2026-09-16 20:28:27', '1', NULL),
('13', '6', 'easy', 'Find the next term in the series: 3, 7, 15, 31, 63, ?', NULL, NULL, '95', '111', '127', '143', 'C', 'Pattern is (Term * 2) + 1. (3*2)+1=7; (7*2)+1=15; (15*2)+1=31; (31*2)+1=63; (63*2)+1 = 127.', '30', '0', '0', 'TCS NQT PYQ', '2026-09-16 20:28:27', '1', NULL),
('14', '8', 'medium', 'Identify the error in the sentence: \"Each of the employees were asked to submit their report by Friday.\"', NULL, NULL, 'Each of the', 'employees were asked', 'to submit their report', 'No error', 'B', 'Subject \"Each\" is singular and requires the singular verb \"was asked\" instead of \"were asked\".', '35', '0', '0', 'TCS NQT PYQ', '2026-09-16 20:28:27', '1', NULL),
('15', '3', 'medium', 'The ratio of ages of A and B is 4:5. Six years hence, the ratio of their ages will be 6:7. What is the present age of B?', NULL, NULL, '12 years', '15 years', '18 years', '20 years', 'B', 'Let present ages be 4x and 5x. After 6 years: (4x+6)/(5x+6) = 6/7 => 7(4x+6) = 6(5x+6) => 28x + 42 = 30x + 36 => 2x = 6 => x = 3. B\'s present age = 5 * 3 = 15 years.', '45', '1', '0', 'Infosys PYQ', '2026-09-16 20:28:27', '1', NULL),
('16', '4', 'hard', '8 persons P, Q, R, S, T, U, V, W sit around a circular table. P is 3rd to left of W who is 2nd to right of R. V is not neighbor of R. Who is directly opposite to P?', NULL, NULL, 'S', 'T', 'U', 'V', 'C', 'Following circular arrangement constraints: Positioning W at top, R 2 positions left of W, P 3 positions left of W. Evaluating remaining constraints places U directly opposite to P.', '60', '0', '0', 'Infosys PYQ', '2026-09-16 20:28:27', '1', NULL),
('17', '5', 'medium', 'Pointing to a man, a woman says, \"His mother is the only daughter of my father.\" How is the woman related to the man?', NULL, NULL, 'Grandmother', 'Mother', 'Sister', 'Aunt', 'B', 'Woman\'s father\'s only daughter is the woman herself. So the man\'s mother is the woman. Thus, the woman is the mother of the man.', '30', '1', '0', 'Infosys PYQ', '2026-09-16 20:28:27', '1', NULL),
('18', '1', 'easy', 'A train 240 m long crosses a 160 m long bridge in 20 seconds. Find the speed of the train in km/h.', NULL, NULL, '54 km/h', '60 km/h', '72 km/h', '80 km/h', 'C', 'Total distance = 240 + 160 = 400 m. Speed in m/s = 400 / 20 = 20 m/s. Convert to km/h: 20 * (18/5) = 72 km/h.', '40', '1', '0', 'Wipro NLTH PYQ', '2026-09-16 20:28:27', '1', NULL),
('19', '2', 'medium', 'By selling an item for $720, a trader loses 10%. At what price should he sell it to gain 20%?', NULL, NULL, '$880', '$960', '$1000', '$1080', 'B', 'Selling price at 90% CP = 720 => Cost Price = 720 / 0.90 = $800. For 20% gain, new SP = 800 * 1.20 = $960.', '35', '0', '0', 'Wipro NLTH PYQ', '2026-09-16 20:28:27', '1', NULL),
('20', '8', 'medium', 'Choose the correct synonym for the word \"BENEVOLENT\":', NULL, NULL, 'Malevolent', 'Generous', 'Hostile', 'Greedy', 'B', 'Benevolent means well-meaning and kindly. Generous is the exact synonym.', '25', '0', '0', 'Wipro NLTH PYQ', '2026-09-16 20:28:27', '1', NULL),
('21', '2', 'hard', 'A population of a town increases by 10% in the 1st year and decreases by 10% in the 2nd year. If current population is 99,000, what was the population 2 years ago?', NULL, NULL, '90,000', '100,000', '110,000', '120,000', 'B', 'Let initial population be P. After 1st year: P * 1.10. After 2nd year: P * 1.10 * 0.90 = P * 0.99 = 99,000 => P = 99,000 / 0.99 = 100,000.', '45', '0', '0', 'Accenture PYQ', '2026-09-16 20:28:27', '1', NULL),
('22', '6', 'medium', 'Complete the letter series: Z, W, T, Q, N, ?', NULL, NULL, 'K', 'L', 'M', 'J', 'A', 'Alphabet positions counting backwards: Z(26), W(23), T(20), Q(17), N(14). Subtract 3 each time: 14 - 3 = 11, which corresponds to K.', '30', '0', '0', 'Accenture PYQ', '2026-09-16 20:28:27', '1', NULL),
('23', '3', 'medium', 'A and B together can complete a work in 12 days. B alone can complete it in 30 days. In how many days can A alone complete the work?', NULL, NULL, '18 days', '20 days', '24 days', '25 days', 'B', '1 day work of A = (1/12) - (1/30) = (5 - 2)/60 = 3/60 = 1/20. Therefore, A alone takes 20 days.', '40', '0', '0', 'Cognizant GenC PYQ', '2026-09-16 20:28:27', '1', NULL),
('24', '7', 'medium', 'Read the snippet: \"Artificial Intelligence is transforming medical diagnostics by detecting anomalies faster than traditional scans.\" What is the main idea?', NULL, NULL, 'AI is replacing all human doctors.', 'AI enhances diagnostic speed and accuracy.', 'Traditional scans are useless.', 'AI requires high hardware cost.', 'B', 'The main idea focuses on AI transforming medical diagnostics by detecting anomalies faster and more accurately.', '40', '0', '0', 'Cognizant GenC PYQ', '2026-09-16 20:28:27', '1', NULL),
('25', '1', 'medium', 'Two pipes A and B can fill a tank in 20 minutes and 30 minutes respectively. If both pipes are opened together, how long will it take to fill the tank?', NULL, NULL, '10 minutes', '12 minutes', '15 minutes', '18 minutes', 'B', 'Combined rate per minute = (1/20) + (1/30) = (3 + 2)/60 = 5/60 = 1/12. Time required = 12 minutes.', '35', '1', '0', 'Capgemini PYQ', '2026-09-16 20:28:27', '1', NULL),
('26', '6', 'easy', 'If CAT is coded as 3120, how is DOG coded in the same system?', NULL, NULL, '4157', '4147', '3157', '4167', 'A', 'Code uses alphabet position numbers: C=3, A=1, T=20 -> 3120. For DOG: D=4, O=15, G=7 -> 4157.', '25', '0', '0', 'Capgemini PYQ', '2026-09-16 20:28:27', '1', NULL),
('27', '9', 'medium', 'A company\'s revenue in 2023 was $50 Million and in 2024 it was $65 Million. What is the percentage growth in revenue?', NULL, NULL, '25%', '30%', '35%', '40%', 'B', 'Growth % = ((65 - 50) / 50) * 100 = (15 / 50) * 100 = 30%.', '30', '0', '0', 'Deloitte PYQ', '2026-09-16 20:28:27', '1', NULL),
('28', '9', 'hard', 'In a pie chart showing expenses, Rent accounts for 108 degrees of the total circle. What percentage of total expenditure is spent on Rent?', NULL, NULL, '25%', '30%', '33.3%', '35%', 'B', 'Percentage = (Angle / 360) * 100 = (108 / 360) * 100 = 0.3 * 100 = 30%.', '35', '0', '0', 'Tech Mahindra PYQ', '2026-09-16 20:28:27', '1', NULL),
('29', '2', 'easy', 'What is 35% of 400 plus 25% of 160?', NULL, NULL, '160', '180', '200', '220', 'B', '35% of 400 = 140. 25% of 160 = 40. Total = 140 + 40 = 180.', '30', '0', '0', 'General Aptitude', '2026-09-16 20:28:27', '0', NULL),
('30', '3', 'hard', 'A mixture of 40 liters contains milk and water in the ratio 3:1. How much water must be added to make the ratio of milk to water 2:1?', NULL, NULL, '5 liters', '6.67 liters', '8 liters', '10 liters', 'A', 'Initial Milk = 30L, Water = 10L. Let w liters of water be added: 30 / (10 + w) = 2/1 => 20 + 2w = 30 => 2w = 10 => w = 5 liters.', '50', '0', '0', 'General Aptitude', '2026-09-16 20:28:27', '0', NULL),
('31', '1', 'hard', 'A person travels from A to B at 30 km/h and returns from B to A at 20 km/h. Find his average speed for the entire journey.', NULL, NULL, '24 km/h', '25 km/h', '26 km/h', '27 km/h', 'A', 'Average Speed = (2 * s1 * s2) / (s1 + s2) = (2 * 30 * 20) / (30 + 20) = 1200 / 50 = 24 km/h.', '40', '1', '1', 'General Aptitude', '2026-09-16 20:28:27', '0', NULL),
('32', '5', 'hard', 'Pointing to a portrait, A says, \"He is the son of the wife of the only son of my father.\" How is A related to the person in the portrait?', NULL, NULL, 'Brother', 'Father', 'Uncle', 'Son', 'B', 'Only son of A\'s father is A himself. Wife of A is A\'s wife. Son of A\'s wife is A\'s son. So A is the father of the person.', '45', '0', '0', 'General Reasoning', '2026-09-16 20:28:27', '0', NULL),
('33', '6', 'medium', 'Find the odd one out: 27, 64, 125, 144, 216', NULL, NULL, '27', '64', '144', '216', 'C', '27=3^3, 64=4^3, 125=5^3, 216=6^3 are all perfect cubes. 144 = 12^2 is a square, not a cube.', '30', '0', '0', 'General Reasoning', '2026-09-16 20:28:27', '0', NULL),
('34', '8', 'easy', 'Fill in the blank: \"She has been living in this city _____ 2015.\"', NULL, NULL, 'for', 'since', 'from', 'during', 'B', '\"Since\" is used for a specific starting point in time (2015) with present perfect continuous tense.', '20', '0', '0', 'Verbal Standard', '2026-09-16 20:28:27', '0', NULL),
('35', '8', 'hard', 'Choose the sentence with correct punctuation and agreement:', NULL, NULL, 'The group of students, along with their teacher, are going on a field trip.', 'The group of students, along with their teacher, is going on a field trip.', 'The group of students along with their teacher were going on a field trip.', 'The group of students along with their teacher have gone on a field trip.', 'B', 'The subject is \"The group\" (singular), so the verb must be singular (\"is going\"). Words introduced by \"along with\" do not change the subject number.', '40', '0', '0', 'Verbal Standard', '2026-09-16 20:28:27', '0', NULL),
('36', '10', 'easy', 'In a certain code language, \"ROSE\" is written as \"TQUG\". How will \"BISCUIT\" be written in that code?', NULL, NULL, 'DKUEWKV', 'DKVGWKV', 'DKUGWKV', 'DKUGVKV', 'C', 'Each letter is shifted forward by +2. B (+2) = D, I (+2) = K, S (+2) = U, C (+2) = E... wait: B->D, I->K, S->U, C->E... R (+2)->T, O (+2)->Q, S (+2)->U, E (+2)->G. BISCUIT: B+2=D, I+2=K, S+2=U, C+2=E, U+2=W, I+2=K, T+2=V -> DKUEWKV or DKUGWKV depending on C+2=E, U+2=W, I+2=K, T+2=V.', '30', '0', '0', 'TCS_NQT_2025', '2026-09-17 18:22:04', '1', NULL),
('37', '10', 'easy', 'If \"COMPUTER\" is written as \"RFUVQNPC\", how is \"MEDICINE\" written in that same code?', NULL, NULL, 'EOJDJEFM', 'EOJDEJFM', 'MFEJDJOE', 'MFEDJJOE', 'A', 'Reverse the order of letters and shift +1 for inner letters: C->C at end, R->R at start. M E D I C I N E reversed and shifted gives EOJDJEFM.', '35', '0', '0', 'INFOSYS_2025', '2026-09-17 18:22:04', '1', NULL),
('38', '10', 'medium', 'If \"A\" = 2, \"M\" = 26, \"Z\" = 52, then what is the code value for \"BET\"?', NULL, NULL, '54', '44', '64', '58', 'A', 'Position number multiplied by 2: B(2*2=4), E(5*2=10), T(20*2=40). Sum = 4 + 10 + 40 = 54.', '30', '0', '0', 'WIPRO_NLTH_2025', '2026-09-17 18:22:04', '1', NULL),
('39', '10', 'medium', 'In a secret military code, \"TEACHER\" is written as \"VGCEJGT\". What will \"CHILDREN\" be coded as?', NULL, NULL, 'EJKNFTGP', 'EJKNGVCP', 'EJKNGKGP', 'EJKNGJGP', 'B', 'Pattern is +2 shift for every character: C(+2)=E, H(+2)=J, I(+2)=K, L(+2)=N, D(+2)=F... wait: D(+2)=F or G? D(4)+2=F(6), R(18)+2=T(20), E(5)+2=G(7), N(14)+2=P(16) => EJKNGVCP.', '30', '0', '0', 'ACCENTURE_2025', '2026-09-17 18:22:04', '1', NULL),
('40', '10', 'hard', 'If \"MACHINE\" is coded as 19-7-9-15-15-20-11, how will \"DANGER\" be coded?', NULL, NULL, '10-7-20-13-11-24', '11-7-20-13-11-24', '13-7-20-9-11-25', '10-7-19-13-11-24', 'A', 'Pattern: Letter position + 6. M(13+6=19), A(1+6=7), C(3+6=9)... D(4+6=10), A(1+6=7), N(14+6=20), G(7+6=13), E(5+6=11), R(18+6=24) => 10-7-20-13-11-24.', '40', '0', '0', 'COGNIZANT_2025', '2026-09-17 18:22:04', '1', NULL),
('41', '10', 'medium', 'In a certain code, \"743\" means \"Mangoes are good\", \"657\" means \"Eat good food\", and \"934\" means \"Mangoes are ripe\". Which digit stands for \"ripe\"?', NULL, NULL, '9', '4', '7', '3', 'A', '\"Mangoes are\" corresponds to common digits \"4\" and \"3\" in 743 and 934. Therefore, \"ripe\" must correspond to \"9\".', '25', '0', '0', 'TCS_NQT_2025', '2026-09-17 18:22:04', '1', NULL),
('42', '11', 'easy', 'Rahul walks 10 km towards North. From there he walks 6 km towards South. Then, he walks 3 km towards East. How far and in which direction is he with reference to his starting point?', NULL, NULL, '5 km West', '5 km North-East', '7 km East', '5 km South-East', 'B', 'North displacement = +10 - 6 = 4 km North. East displacement = 3 km East. Distance = sqrt(4^2 + 3^2) = sqrt(25) = 5 km North-East.', '35', '0', '0', 'INFOSYS_2025', '2026-09-17 18:22:04', '1', NULL),
('43', '11', 'medium', 'A man is facing West. He turns 45 degrees in the clockwise direction and then another 180 degrees in the same direction and then 270 degrees in the counter-clockwise direction. Which direction is he facing now?', NULL, NULL, 'South-West', 'North-West', 'South', 'East', 'A', 'Net turn = +45 + 180 - 270 = -45 degrees (45 deg counter-clockwise). Starting at West, turning 45 deg counter-clockwise lands at South-West.', '35', '0', '0', 'WIPRO_NLTH_2025', '2026-09-17 18:22:04', '1', NULL),
('44', '11', 'medium', 'One morning after sunrise, Suresh was standing facing a pole. The shadow of the pole fell exactly to his right. To which direction was Suresh facing?', NULL, NULL, 'East', 'West', 'South', 'North', 'C', 'In the morning, the sun is in the East, so shadows fall towards the West. If the shadow is to Suresh\'s right, West is to his right, which means Suresh is facing South.', '30', '0', '0', 'ACCENTURE_2025', '2026-09-17 18:22:04', '1', NULL),
('45', '11', 'hard', 'K is 40 m South-West of L. If M is 40 m South-East of L, then M is in which direction of K?', NULL, NULL, 'East', 'West', 'North-East', 'South-East', 'A', 'L is at (0,0). K is at (-28.28, -28.28). M is at (28.28, -28.28). Comparing M relative to K: M has the same Y-coordinate but greater X-coordinate, so M is due East of K.', '40', '0', '0', 'COGNIZANT_2025', '2026-09-17 18:22:04', '1', NULL),
('46', '11', 'medium', 'A car travels 8 km East, turns right and drives 5 km, then turns right again and drives 8 km. How far is the car from its starting point?', NULL, NULL, '5 km', '8 km', '13 km', '16 km', 'A', 'East 8 km, South 5 km, West 8 km leaves the car 5 km South of the starting point.', '25', '0', '0', 'TCS_NQT_2025', '2026-09-17 18:22:04', '1', NULL),
('47', '12', 'easy', 'A can complete a project in 15 days, and B can complete the same project in 10 days. How long will they take working together?', NULL, NULL, '5 days', '6 days', '7.5 days', '8 days', 'B', 'Combined rate per day = 1/15 + 1/10 = 5/30 = 1/6. Days required = 6 days.', '30', '0', '0', 'CAMPUS_PLACEMENT_2025', '2026-09-17 18:22:04', '1', NULL),
('48', '12', 'medium', 'A and B together can do a piece of work in 12 days, which B and C can do in 16 days. After A has been working at it for 5 days and B for 7 days, C finishes it in 13 days. In how many days C alone can do the work?', NULL, NULL, '16 days', '24 days', '36 days', '48 days', 'B', '5A + 7B + 13C = 1 => 5(A+B) + 2(B+C) + 11C = 1 => 5(1/12) + 2(1/16) + 11C = 1 => 5/12 + 1/8 + 11C = 1 => 13/24 + 11C = 1 => 11C = 11/24 => C = 1/24. C takes 24 days.', '50', '0', '0', 'BANK_PO_2025', '2026-09-17 18:22:04', '1', NULL),
('49', '12', 'hard', 'Two pipes A and B can fill a tank in 12 minutes and 15 minutes respectively. If both are opened together and after 3 minutes A is closed, how much more time will B take to fill the tank?', NULL, NULL, '7 minutes 15 seconds', '8 minutes 15 seconds', '8 minutes 30 seconds', '9 minutes', 'B', 'In 3 minutes, (A+B) fill 3 * (1/12 + 1/15) = 3 * (9/60) = 27/60 = 9/20 of tank. Remaining tank = 11/20. B fills at 1/15 per min. Time for B = (11/20) / (1/15) = 33/4 = 8.25 minutes = 8 mins 15 secs.', '45', '0', '0', 'TCS_NQT_2025', '2026-09-17 18:22:04', '1', NULL),
('50', '1', 'medium', 'A train running at 54 km/h crosses a platform 180 m long in 20 seconds. What is the length of the train?', NULL, NULL, '120 m', '140 m', '150 m', '160 m', 'A', 'Speed in m/s = 54 * (5/18) = 15 m/s. Total distance in 20 seconds = 15 * 20 = 300 m. Train length = 300 - 180 = 120 m.', '35', '1', '0', 'INFOSYS_2025', '2026-09-17 18:22:04', '1', NULL);
INSERT INTO `questions` (`id`, `subtopic_id`, `difficulty`, `question_text`, `code_snippet`, `language`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_option`, `explanation`, `est_time_seconds`, `total_attempts_count`, `total_correct_count`, `source_tag`, `created_at`, `is_company_pyq`, `company_name`) VALUES
('51', '1', 'hard', 'Walking at 3/4 of his usual speed, a man reaches his office 20 minutes late. Find his usual time to reach the office.', NULL, NULL, '45 minutes', '60 minutes', '75 minutes', '80 minutes', 'B', 'Ratio of usual speed to new speed = 4:3. Ratio of usual time to new time = 3:4. Difference in time units = 1 unit = 20 minutes. Usual time = 3 units = 60 minutes.', '40', '1', '0', 'WIPRO_NLTH_2025', '2026-09-17 18:22:04', '1', NULL),
('52', '1', 'medium', 'A boat moves downstream at the rate of 1 km in 6 minutes and upstream at 1 km in 10 minutes. What is the speed of the current in km/h?', NULL, NULL, '1 km/h', '2 km/h', '3 km/h', '4 km/h', 'B', 'Downstream speed (u) = 1 km / (6/60 h) = 10 km/h. Upstream speed (v) = 1 km / (10/60 h) = 6 km/h. Speed of current = (u - v)/2 = (10 - 6)/2 = 2 km/h.', '35', '0', '0', 'ACCENTURE_2025', '2026-09-17 18:22:04', '1', NULL),
('53', '2', 'easy', 'A student needs 40% marks to pass an exam. If he gets 178 marks and fails by 22 marks, what is the maximum marks of the exam?', NULL, NULL, '400', '500', '600', '450', 'B', 'Passing marks = 178 + 22 = 200. Since 40% of Maximum Marks = 200, Max Marks = 200 / 0.40 = 500.', '30', '0', '0', 'COGNIZANT_2025', '2026-09-17 18:22:04', '1', NULL),
('54', '2', 'medium', 'A shopkeeper marks his goods 20% above the cost price and allows a discount of 10%. What is his net profit percentage?', NULL, NULL, '8%', '10%', '12%', '14%', 'A', 'Let CP = 100. Marked Price = 120. Selling Price = 120 * 0.90 = 108. Net Profit % = 108 - 100 = 8%.', '30', '0', '0', 'TCS_NQT_2025', '2026-09-17 18:22:04', '1', NULL),
('55', '2', 'hard', 'If the cost price of 15 articles is equal to the selling price of 12 articles, what is the gain percentage?', NULL, NULL, '20%', '25%', '30%', '33.33%', 'B', '15 CP = 12 SP => SP/CP = 15/12 = 5/4. Gain % = ((5 - 4) / 4) * 100 = 25%.', '35', '0', '0', 'INFOSYS_2025', '2026-09-17 18:22:04', '1', NULL),
('56', '3', 'easy', 'If A : B = 2 : 3 and B : C = 4 : 5, find the ratio A : B : C.', NULL, NULL, '8 : 12 : 15', '6 : 12 : 15', '8 : 10 : 15', '2 : 4 : 5', 'A', 'Multiply first ratio by 4 and second ratio by 3 to equalize B: A:B = 8:12, B:C = 12:15 => A:B:C = 8:12:15.', '25', '0', '0', 'WIPRO_NLTH_2025', '2026-09-17 18:22:04', '1', NULL),
('57', '3', 'medium', 'The sum of ages of 5 children born at intervals of 3 years each is 50 years. What is the age of the youngest child?', NULL, NULL, '4 years', '6 years', '8 years', '10 years', 'A', 'Let ages be x, x+3, x+6, x+9, x+12. Sum = 5x + 30 = 50 => 5x = 20 => x = 4 years.', '30', '0', '0', 'ACCENTURE_2025', '2026-09-17 18:22:04', '1', NULL),
('58', '4', 'medium', 'Five friends A, B, C, D, E are sitting in a row facing North. A is sitting next to B, C is sitting next to D, D is not sitting with E who is on the left end of the bench. C is on the second position from the right. A is to the right of B and E. A and C are sitting together. In which position is A sitting?', NULL, NULL, 'Between B and C', 'Extreme left', 'Extreme right', 'Between C and D', 'A', 'Order from left to right: E, B, A, C, D. A sits between B and C.', '40', '0', '0', 'TCS_NQT_2025', '2026-09-17 18:22:04', '1', NULL),
('59', '4', 'hard', '6 people A, B, C, D, E, F sit around a circular table facing center. A is opposite to D. B is sitting between A and C. E is opposite to B. Who is sitting to the immediate right of A?', NULL, NULL, 'B', 'C', 'F', 'E', 'A', 'Arranging in circle: A with B to one side and F to the other. B sits between A and C, so B is to immediate right of A when facing center.', '45', '0', '0', 'COGNIZANT_2025', '2026-09-17 18:22:04', '1', NULL),
('60', '5', 'medium', 'Pointing to a photograph, X says, \"She is the daughter of my grandfather\'s only son.\" How is the girl in the photograph related to X?', NULL, NULL, 'Mother', 'Sister', 'Cousin', 'Aunt', 'B', 'Grandfather\'s only son is X\'s father. Daughter of X\'s father is X\'s sister.', '25', '0', '0', 'INFOSYS_2025', '2026-09-17 18:22:04', '1', NULL),
('61', '5', 'hard', 'If A + B means A is the brother of B; A - B means A is the sister of B; and A * B means A is the father of B. Which of the following means that C is the nephew of M?', NULL, NULL, 'M - N + C * F', 'N * M + C - F', 'M + N * C - F', 'N + M - C * F', 'C', 'In M + N * C - F: M is brother of N, N is father of C, C is sister of F. Since C is child of M\'s brother N, C is nephew/niece of M.', '45', '0', '0', 'BANK_PO_2025', '2026-09-17 18:22:04', '1', NULL),
('62', '6', 'easy', 'Find the missing number in the series: 4, 9, 19, 39, 79, ?', NULL, NULL, '119', '139', '159', '169', 'C', 'Pattern is (Term * 2) + 1. (4*2)+1=9, (9*2)+1=19, (19*2)+1=39, (39*2)+1=79, (79*2)+1 = 159.', '25', '0', '0', 'WIPRO_NLTH_2025', '2026-09-17 18:22:04', '1', NULL),
('63', '6', 'medium', 'What comes next in the sequence: AZ, BY, CX, DW, ?', NULL, NULL, 'EV', 'FU', 'EX', 'VE', 'A', 'First letters go forward (A, B, C, D, E), second letters go backward (Z, Y, X, W, V). Next pair is EV.', '20', '0', '0', 'ACCENTURE_2025', '2026-09-17 18:22:04', '1', NULL),
('64', '13', 'easy', 'What is the meaning of the idiom \"To burn the candle at both ends\"?', NULL, NULL, 'To be stingy', 'To work extremely hard without rest', 'To waste energy on useless things', 'To celebrate enthusiastically', 'B', 'To burn the candle at both ends means to exhaust oneself by working early morning and late night without sufficient rest.', '20', '0', '0', 'CAMPUS_PLACEMENT_2025', '2026-09-17 18:22:04', '1', NULL),
('65', '13', 'medium', 'Choose the word that best means \"Existing or spreading everywhere\":', NULL, NULL, 'Ubiquitous', 'Ephemeral', 'Esoteric', 'Transient', 'A', 'Ubiquitous means present, appearing, or found everywhere.', '20', '0', '0', 'TCS_NQT_2025', '2026-09-17 18:22:04', '1', NULL),
('66', '13', 'medium', 'The root word \"PHIL\" means love. What does \"Philanthropist\" mean?', NULL, NULL, 'A lover of books', 'A lover of mankind who donates to good causes', 'A lover of nature and environment', 'A lover of music and arts', 'B', 'Phil (love) + Anthrop (humanity/mankind) = A lover of mankind who promotes human welfare.', '20', '0', '0', 'INFOSYS_2025', '2026-09-17 18:22:04', '1', NULL),
('67', '7', 'medium', '\"Quantum computing promises to revolutionize encryption, but current hardware still suffers from high decoherence rates.\" What is the main challenge mentioned?', NULL, NULL, 'High manufacturing cost', 'Lack of quantum algorithms', 'High decoherence rates in hardware', 'Slow processing speed', 'C', 'The passage explicitly identifies \"high decoherence rates\" as the hardware issue facing quantum computing.', '30', '0', '0', 'COGNIZANT_2025', '2026-09-17 18:22:04', '1', NULL),
('68', '8', 'medium', 'Choose the correct sentence:', NULL, NULL, 'Neither of the candidates have submitted their resume.', 'Neither of the candidates has submitted his or her resume.', 'Neither of the candidate have submitted their resume.', 'Neither of the candidates were submitted their resume.', 'B', '\"Neither\" takes a singular verb (\"has submitted\"). Option B is grammatically precise.', '30', '0', '0', 'ACCENTURE_2025', '2026-09-17 18:22:04', '1', NULL),
('69', '1', 'medium', 'A man can row 6 km/h in still water. If the speed of the current is 2 km/h, it takes him 4 hours to row to a place and come back. Find the distance to the place.', NULL, NULL, '8 km', '9.6 km', '10 km', '12 km', 'B', 'Downstream speed (u) = 6 + 2 = 8 km/h. Upstream speed (v) = 6 - 2 = 4 km/h. Time formula: T = D/u + D/v => 4 = D/8 + D/4 => 4 = 3D/8 => D = 32/3 = 10.67 or D = (8 * 4 * 4)/(8+4) = 128/12 = 9.6 km (using D = t * (u*v)/(u+v)).', '50', '1', '0', 'TCS NQT PYQ', '2026-09-17 18:22:21', '1', NULL),
('70', '2', 'hard', 'A sum of money becomes 3 times itself in 6 years at Compound Interest. In how many years will it become 27 times itself at the same rate of interest?', NULL, NULL, '12 years', '18 years', '24 years', '30 years', 'B', 'If money becomes 3^1 in 6 years, it becomes (3^1)^n = 3^n in 6 * n years. Here 27 = 3^3. So time required = 6 * 3 = 18 years.', '45', '0', '0', 'TCS NQT PYQ', '2026-09-17 18:22:21', '1', NULL),
('71', '6', 'easy', 'Find the next term in the series: 3, 7, 15, 31, 63, ?', NULL, NULL, '95', '111', '127', '143', 'C', 'Pattern is (Term * 2) + 1. (3*2)+1=7; (7*2)+1=15; (15*2)+1=31; (31*2)+1=63; (63*2)+1 = 127.', '30', '0', '0', 'TCS NQT PYQ', '2026-09-17 18:22:21', '1', NULL),
('72', '8', 'medium', 'Identify the error in the sentence: \"Each of the employees were asked to submit their report by Friday.\"', NULL, NULL, 'Each of the', 'employees were asked', 'to submit their report', 'No error', 'B', 'Subject \"Each\" is singular and requires the singular verb \"was asked\" instead of \"were asked\".', '35', '0', '0', 'TCS NQT PYQ', '2026-09-17 18:22:21', '1', NULL),
('73', '3', 'medium', 'The ratio of ages of A and B is 4:5. Six years hence, the ratio of their ages will be 6:7. What is the present age of B?', NULL, NULL, '12 years', '15 years', '18 years', '20 years', 'B', 'Let present ages be 4x and 5x. After 6 years: (4x+6)/(5x+6) = 6/7 => 7(4x+6) = 6(5x+6) => 28x + 42 = 30x + 36 => 2x = 6 => x = 3. B\'s present age = 5 * 3 = 15 years.', '45', '0', '0', 'Infosys PYQ', '2026-09-17 18:22:21', '1', NULL),
('74', '4', 'hard', '8 persons P, Q, R, S, T, U, V, W sit around a circular table. P is 3rd to left of W who is 2nd to right of R. V is not neighbor of R. Who is directly opposite to P?', NULL, NULL, 'S', 'T', 'U', 'V', 'C', 'Following circular arrangement constraints: Positioning W at top, R 2 positions left of W, P 3 positions left of W. Evaluating remaining constraints places U directly opposite to P.', '60', '0', '0', 'Infosys PYQ', '2026-09-17 18:22:21', '1', NULL),
('75', '5', 'medium', 'Pointing to a man, a woman says, \"His mother is the only daughter of my father.\" How is the woman related to the man?', NULL, NULL, 'Grandmother', 'Mother', 'Sister', 'Aunt', 'B', 'Woman\'s father\'s only daughter is the woman herself. So the man\'s mother is the woman. Thus, the woman is the mother of the man.', '30', '0', '0', 'Infosys PYQ', '2026-09-17 18:22:21', '1', NULL),
('76', '1', 'easy', 'A train 240 m long crosses a 160 m long bridge in 20 seconds. Find the speed of the train in km/h.', NULL, NULL, '54 km/h', '60 km/h', '72 km/h', '80 km/h', 'C', 'Total distance = 240 + 160 = 400 m. Speed in m/s = 400 / 20 = 20 m/s. Convert to km/h: 20 * (18/5) = 72 km/h.', '40', '0', '0', 'Wipro NLTH PYQ', '2026-09-17 18:22:21', '1', NULL),
('77', '2', 'medium', 'By selling an item for $720, a trader loses 10%. At what price should he sell it to gain 20%?', NULL, NULL, '$880', '$960', '$1000', '$1080', 'B', 'Selling price at 90% CP = 720 => Cost Price = 720 / 0.90 = $800. For 20% gain, new SP = 800 * 1.20 = $960.', '35', '0', '0', 'Wipro NLTH PYQ', '2026-09-17 18:22:21', '1', NULL),
('78', '8', 'medium', 'Choose the correct synonym for the word \"BENEVOLENT\":', NULL, NULL, 'Malevolent', 'Generous', 'Hostile', 'Greedy', 'B', 'Benevolent means well-meaning and kindly. Generous is the exact synonym.', '25', '0', '0', 'Wipro NLTH PYQ', '2026-09-17 18:22:21', '1', NULL),
('79', '2', 'hard', 'A population of a town increases by 10% in the 1st year and decreases by 10% in the 2nd year. If current population is 99,000, what was the population 2 years ago?', NULL, NULL, '90,000', '100,000', '110,000', '120,000', 'B', 'Let initial population be P. After 1st year: P * 1.10. After 2nd year: P * 1.10 * 0.90 = P * 0.99 = 99,000 => P = 99,000 / 0.99 = 100,000.', '45', '0', '0', 'Accenture PYQ', '2026-09-17 18:22:21', '1', NULL),
('80', '6', 'medium', 'Complete the letter series: Z, W, T, Q, N, ?', NULL, NULL, 'K', 'L', 'M', 'J', 'A', 'Alphabet positions counting backwards: Z(26), W(23), T(20), Q(17), N(14). Subtract 3 each time: 14 - 3 = 11, which corresponds to K.', '30', '0', '0', 'Accenture PYQ', '2026-09-17 18:22:21', '1', NULL),
('81', '3', 'medium', 'A and B together can complete a work in 12 days. B alone can complete it in 30 days. In how many days can A alone complete the work?', NULL, NULL, '18 days', '20 days', '24 days', '25 days', 'B', '1 day work of A = (1/12) - (1/30) = (5 - 2)/60 = 3/60 = 1/20. Therefore, A alone takes 20 days.', '40', '0', '0', 'Cognizant GenC PYQ', '2026-09-17 18:22:21', '1', NULL),
('82', '7', 'medium', 'Read the snippet: \"Artificial Intelligence is transforming medical diagnostics by detecting anomalies faster than traditional scans.\" What is the main idea?', NULL, NULL, 'AI is replacing all human doctors.', 'AI enhances diagnostic speed and accuracy.', 'Traditional scans are useless.', 'AI requires high hardware cost.', 'B', 'The main idea focuses on AI transforming medical diagnostics by detecting anomalies faster and more accurately.', '40', '0', '0', 'Cognizant GenC PYQ', '2026-09-17 18:22:21', '1', NULL),
('83', '1', 'medium', 'Two pipes A and B can fill a tank in 20 minutes and 30 minutes respectively. If both pipes are opened together, how long will it take to fill the tank?', NULL, NULL, '10 minutes', '12 minutes', '15 minutes', '18 minutes', 'B', 'Combined rate per minute = (1/20) + (1/30) = (3 + 2)/60 = 5/60 = 1/12. Time required = 12 minutes.', '35', '0', '0', 'Capgemini PYQ', '2026-09-17 18:22:21', '1', NULL),
('84', '6', 'easy', 'If CAT is coded as 3120, how is DOG coded in the same system?', NULL, NULL, '4157', '4147', '3157', '4167', 'A', 'Code uses alphabet position numbers: C=3, A=1, T=20 -> 3120. For DOG: D=4, O=15, G=7 -> 4157.', '25', '0', '0', 'Capgemini PYQ', '2026-09-17 18:22:21', '1', NULL),
('85', '9', 'medium', 'A company\'s revenue in 2023 was $50 Million and in 2024 it was $65 Million. What is the percentage growth in revenue?', NULL, NULL, '25%', '30%', '35%', '40%', 'B', 'Growth % = ((65 - 50) / 50) * 100 = (15 / 50) * 100 = 30%.', '30', '0', '0', 'Deloitte PYQ', '2026-09-17 18:22:21', '1', NULL),
('86', '9', 'hard', 'In a pie chart showing expenses, Rent accounts for 108 degrees of the total circle. What percentage of total expenditure is spent on Rent?', NULL, NULL, '25%', '30%', '33.3%', '35%', 'B', 'Percentage = (Angle / 360) * 100 = (108 / 360) * 100 = 0.3 * 100 = 30%.', '35', '0', '0', 'Tech Mahindra PYQ', '2026-09-17 18:22:21', '1', NULL),
('87', '2', 'easy', 'What is 35% of 400 plus 25% of 160?', NULL, NULL, '160', '180', '200', '220', 'B', '35% of 400 = 140. 25% of 160 = 40. Total = 140 + 40 = 180.', '30', '0', '0', 'General Aptitude', '2026-09-17 18:22:21', '0', NULL),
('88', '3', 'hard', 'A mixture of 40 liters contains milk and water in the ratio 3:1. How much water must be added to make the ratio of milk to water 2:1?', NULL, NULL, '5 liters', '6.67 liters', '8 liters', '10 liters', 'A', 'Initial Milk = 30L, Water = 10L. Let w liters of water be added: 30 / (10 + w) = 2/1 => 20 + 2w = 30 => 2w = 10 => w = 5 liters.', '50', '0', '0', 'General Aptitude', '2026-09-17 18:22:21', '0', NULL),
('89', '1', 'hard', 'A person travels from A to B at 30 km/h and returns from B to A at 20 km/h. Find his average speed for the entire journey.', NULL, NULL, '24 km/h', '25 km/h', '26 km/h', '27 km/h', 'A', 'Average Speed = (2 * s1 * s2) / (s1 + s2) = (2 * 30 * 20) / (30 + 20) = 1200 / 50 = 24 km/h.', '40', '0', '0', 'General Aptitude', '2026-09-17 18:22:21', '0', NULL),
('90', '5', 'hard', 'Pointing to a portrait, A says, \"He is the son of the wife of the only son of my father.\" How is A related to the person in the portrait?', NULL, NULL, 'Brother', 'Father', 'Uncle', 'Son', 'B', 'Only son of A\'s father is A himself. Wife of A is A\'s wife. Son of A\'s wife is A\'s son. So A is the father of the person.', '45', '0', '0', 'General Reasoning', '2026-09-17 18:22:21', '0', NULL),
('91', '6', 'medium', 'Find the odd one out: 27, 64, 125, 144, 216', NULL, NULL, '27', '64', '144', '216', 'C', '27=3^3, 64=4^3, 125=5^3, 216=6^3 are all perfect cubes. 144 = 12^2 is a square, not a cube.', '30', '1', '0', 'General Reasoning', '2026-09-17 18:22:21', '0', NULL),
('92', '8', 'easy', 'Fill in the blank: \"She has been living in this city _____ 2015.\"', NULL, NULL, 'for', 'since', 'from', 'during', 'B', '\"Since\" is used for a specific starting point in time (2015) with present perfect continuous tense.', '20', '0', '0', 'Verbal Standard', '2026-09-17 18:22:21', '0', NULL),
('93', '8', 'hard', 'Choose the sentence with correct punctuation and agreement:', NULL, NULL, 'The group of students, along with their teacher, are going on a field trip.', 'The group of students, along with their teacher, is going on a field trip.', 'The group of students along with their teacher were going on a field trip.', 'The group of students along with their teacher have gone on a field trip.', 'B', 'The subject is \"The group\" (singular), so the verb must be singular (\"is going\"). Words introduced by \"along with\" do not change the subject number.', '40', '0', '0', 'Verbal Standard', '2026-09-17 18:22:21', '0', NULL),
