('620', '8', 'easy', 'Identify the error: \'The manager along with his team members (have / has) arrived at the client office.\'', NULL, NULL, 'Use \'has\' because \'manager\' is the singular subject', 'Use \'have\' because of \'team members\'', 'Replace \'arrived\' with \'arriving\'', 'No error', 'A', 'Subject-verb agreement rule: \'along with\' doesn\'t pluralize the primary subject (TCS NQT pattern).', '45', '0', '0', 'TCS NQT PYQ', '2026-09-18 08:01:45', '1', 'TCS NQT'),
('621', '9', 'easy', 'A table shows sales revenue for Q1=$180M and Q2=$230M. Find the percentage growth.', NULL, NULL, '27.78%', '32.78%', '24.78%', '37.78%', 'A', 'Quarterly growth percentage formula applied for TCS NQT data interpretation.', '45', '0', '0', 'TCS NQT PYQ', '2026-09-18 08:01:45', '1', 'TCS NQT'),
